/**
 * Regenerates NARRATION-CHECKLIST.md at the repo root — the human-readable
 * ledger of the narration shelf, Modernity-checklist style. Do not edit the
 * checklist by hand; this script is the only writer.
 *
 *   node scripts/narration/build-narration-checklist.mjs
 *
 * Two sources, unioned:
 *   1. public/narration-v1.json — the manifest the installed apps read. Every
 *      books[id].voices[persona] entry is a finished pair. This is what keeps
 *      the committed checklist cumulative: work/ is deletable scratch and a CI
 *      runner only ever holds the current wave's folders, so a checklist built
 *      from work/ alone forgot every earlier wave (9/9 → 36/45 → 54/63 → 12/21
 *      while the manifest only ever grew).
 *   2. scripts/narration/work/ — the live run. Adds the in-progress (☐),
 *      failed (✗) and excluded.json rows the manifest cannot know about yet.
 *
 * Run build-manifest.mjs first (the workflows do) so the manifest already
 * carries this run's verified pairs; a pair finished in work/ but not merged
 * yet still shows ☑ from its status.json.
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..', '..');
const WORK = path.join(HERE, 'work');
const MANIFEST = path.join(ROOT, 'public', 'narration-v1.json');
const VOICES = JSON.parse(readFileSync(path.join(HERE, 'voices.json'), 'utf8'));
const personas = Object.keys(VOICES.personas);

const readJson = (p) => (existsSync(p) ? JSON.parse(readFileSync(p, 'utf8')) : null);

// 1. Finished pairs, from the manifest.
const shipped = readJson(MANIFEST)?.books ?? {};

// 2. Row list: every manifest book plus every numeric work/ folder.
const ids = new Set(Object.keys(shipped));
if (existsSync(WORK)) for (const d of readdirSync(WORK)) if (/^\d+$/.test(d)) ids.add(d);

const lines = [];
lines.push('# Narration checklist');
lines.push('');
lines.push('Generated by `node scripts/narration/build-narration-checklist.mjs` — do not edit by hand.');
lines.push('The pipeline and run order live in `docs/narration-plan.md` §13.');
lines.push('Finished pairs come from `public/narration-v1.json`, the manifest the installed apps read.');
lines.push('In-progress, failed and excluded rows come from the live `scripts/narration/work/` run.');
lines.push('');

let done = 0;
let total = 0;
let fromManifest = 0;
const rows = [];
const excluded = [];

for (const id of [...ids].sort((a, b) => Number(a) - Number(b))) {
    const ex = readJson(path.join(WORK, id, 'excluded.json'));
    if (ex) {
        // The two sources disagree if a shipped book is excluded on re-plan;
        // say so rather than hide the shipped voices behind the exclusion.
        const still = Object.keys(shipped[id]?.voices ?? {});
        const note = still.length ? ` (still shipped in the manifest: ${still.join(', ')})` : '';
        excluded.push(`- ${id} — ${ex.reason}: token ${ex.hits[0].token} \`${ex.hits[0].word}\` (${ex.hits.length} hit(s))${note}`);
        continue;
    }
    const marks = personas.map((p) => {
        total++;
        if (shipped[id]?.voices?.[p]) { done++; fromManifest++; return `☑ ${p}`; }
        const s = readJson(path.join(WORK, id, p, 'status.json'));
        if (!s) return `☐ ${p}`;
        if (s.ok) { done++; return `☑ ${p}`; }
        return `✗ ${p} (${(s.error || 'failed').slice(0, 60)})`;
    });
    rows.push(`- ${id}: ${marks.join('  ')}`);
}

lines.push(`**${done} / ${total}** book×voice pairs finished across ${rows.length} book(s).`);
lines.push('');
lines.push(...rows);
if (excluded.length) {
    lines.push('');
    lines.push('## Excluded by the leftover gate (not narratable until a coordinated re-strip + re-anchor)');
    lines.push(...excluded);
}
lines.push('');

writeFileSync(path.join(ROOT, 'NARRATION-CHECKLIST.md'), lines.join('\n'));
console.log(`NARRATION-CHECKLIST.md regenerated (${done}/${total} done across ${rows.length} book(s), ${fromManifest} pair(s) from the manifest, ${excluded.length} excluded).`);
